/**
 * Reading an answer: which way it runs, and what shape it has.
 *
 * Kept apart from the component that draws it so both can be tested as
 * plain functions, and so the file that exports a component exports only
 * that.
 */

/*
 * Characters that carry a direction of their own.
 *
 * Written as ranges rather than a regular expression because a character
 * class over these blocks is exactly what `no-misleading-character-class`
 * exists to catch: several of them hold marks that only mean anything
 * attached to the letter before them. Comparing code points asks the
 * question one character at a time, which is the question being asked.
 *
 * The Arabic blocks have their digits cut out. Arabic-Indic digits are
 * weak, not strong: a Persian sentence opening with a year is still
 * Persian, and an English one opening with the same year is still English,
 * so neither may decide the direction on its own.
 */
const RTL_RANGES: [number, number][] = [
  [0x0590, 0x05ff], // Hebrew
  [0x0606, 0x065f], // Arabic, above the format characters
  [0x066a, 0x06ef], // Arabic, above the Arabic-Indic digits
  [0x06fa, 0x06ff], // Arabic, above the extended digits
  [0x0700, 0x074f], // Syriac
  [0x0750, 0x077f], // Arabic Supplement
  [0x0780, 0x07bf], // Thaana
  [0x07c0, 0x07ff], // NKo
  [0x08a0, 0x08ff], // Arabic Extended-A
  [0xfb1d, 0xfdff], // Hebrew and Arabic presentation forms
  [0xfe70, 0xfeff], // Arabic presentation forms B
];

const LTR_RANGES: [number, number][] = [
  [0x0041, 0x005a], // A-Z
  [0x0061, 0x007a], // a-z
  [0x00c0, 0x02ff], // Latin supplements and extensions
  [0x0370, 0x058f], // Greek, Cyrillic, Armenian
  [0x0900, 0x1fff], // Indic, South-East Asian, Georgian, Greek extended
  [0x2c00, 0xd7ff], // the rest of the left-to-right scripts
];

function within(code: number, ranges: [number, number][]): boolean {
  return ranges.some(([low, high]) => code >= low && code <= high);
}

/**
 * Which way a piece of text runs, by the first letter in it that carries a
 * direction of its own. Nothing yet if there is none.
 *
 * This is the rule for something being typed, and it is deliberately not
 * the one below. A field that re-counted its scripts on every keystroke
 * would swing from one side to the other in the middle of a sentence as
 * one language overtook the other; the first letter decides and then it
 * stays, which is what every messaging app does and what a person typing
 * expects. Weak characters -- digits, spaces, punctuation -- decide
 * nothing, so a question that opens with a year or a quotation mark waits
 * for a real letter before it picks a side.
 */
export function firstStrongDir(text: string): 'ltr' | 'rtl' | undefined {
  for (const char of text) {
    const code = char.codePointAt(0);
    if (code === undefined) continue;
    if (within(code, RTL_RANGES)) return 'rtl';
    if (within(code, LTR_RANGES)) return 'ltr';
  }
  return undefined;
}

/**
 * Which way a piece of text runs, by which script most of it is in.
 *
 * Not the first strong letter, which is what dir="auto" uses. Lex answers a
 * Persian learner about English words, so half its sentences open with an
 * English headword and then run in Persian for a line and a half -- and
 * first-strong lays every one of those out left to right, with the full
 * stop stranded on the wrong side. What a reader means by "this sentence is
 * Persian" is which script most of it is in, so that is what is counted.
 *
 * It is decided here rather than with dir="auto" because "auto" leaves no
 * hook for CSS, and the one that exists, :dir(), is rewritten by this
 * build's PostCSS into a list of :lang() tests -- which asks what language
 * the element is tagged as, and the tag here is the notebook's.
 */
export function dirOf(text: string): 'ltr' | 'rtl' {
  let rtl = 0;
  let ltr = 0;
  for (const char of text) {
    const code = char.codePointAt(0);
    if (code === undefined) continue;
    if (within(code, RTL_RANGES)) rtl += 1;
    else if (within(code, LTR_RANGES)) ltr += 1;
  }
  return rtl > ltr ? 'rtl' : 'ltr';
}

/** A paragraph, or one list with its items. */
type Block = { kind: 'p'; text: string } | { kind: 'list'; ordered: boolean; items: string[] };

const BULLET = /^\s*[-*•]\s+(.*)$/;
const NUMBERED = /^\s*\d+[.)]\s+(.*)$/;
/** A heading, which in a chat is a strong line rather than a title. */
const HEADING = /^\s*#{1,6}\s+(.*)$/;

export function blocksOf(text: string): Block[] {
  const blocks: Block[] = [];
  let paragraph: string[] = [];
  let list: { ordered: boolean; items: string[] } | null = null;

  const endParagraph = (): void => {
    if (paragraph.length > 0) {
      blocks.push({ kind: 'p', text: paragraph.join('\n') });
      paragraph = [];
    }
  };
  const endList = (): void => {
    if (list !== null) {
      blocks.push({ kind: 'list', ordered: list.ordered, items: list.items });
      list = null;
    }
  };

  for (const line of text.split('\n')) {
    const bullet = BULLET.exec(line);
    const numbered = NUMBERED.exec(line);
    const heading = HEADING.exec(line);

    if (bullet !== null || numbered !== null) {
      const ordered = numbered !== null;
      const item = (numbered?.[1] ?? bullet?.[1] ?? '').trim();
      endParagraph();
      // A list that changes kind mid-way is two lists, which is what the
      // model meant even when it did not say so.
      if (list !== null && list.ordered !== ordered) endList();
      list ??= { ordered, items: [] };
      list.items.push(item);
      continue;
    }

    endList();
    if (line.trim() === '') {
      endParagraph();
      continue;
    }
    paragraph.push(heading !== null ? `**${heading[1] ?? ''}**` : line);
  }
  endParagraph();
  endList();
  return blocks;
}
