import { useEffect, useState } from 'react';
import { ttsLocaleOf, type LanguageCode } from '@lexpad/core';
import { Icon } from '@/components/ui/Icon.js';
import { scriptClass } from '@/components/ui/script.js';
import { Sheet } from '@/components/ui/Sheet.js';
import { platform } from '@/lib/platform/index.js';
import { useCanSpeak } from '@/lib/useCanSpeak.js';
import { cx } from '@/lib/cx.js';
import { t, type MessageKey } from '@/i18n/index.js';
import type { ApiLexReason } from '@/api/types.js';
import { Rich } from './rich.js';
import { dirOf } from './richText.js';
import type { ChatMessage } from './useLexChat.js';
import styles from './Assistant.module.css';

/** How long the copy button stays showing that it worked. */
const COPIED_FOR_MS = 1600;

/** The short list offered after a thumbs down, in the order they happen. */
const REASONS: ApiLexReason[] = ['wrong', 'unhelpful', 'confusing', 'too_long', 'wrong_language', 'other'];

const REASON_LABEL: Record<ApiLexReason, MessageKey> = {
  wrong: 'assistant.reason.wrong',
  unhelpful: 'assistant.reason.unhelpful',
  confusing: 'assistant.reason.confusing',
  too_long: 'assistant.reason.tooLong',
  wrong_language: 'assistant.reason.wrongLanguage',
  other: 'assistant.reason.other',
};

/**
 * One turn of the conversation.
 *
 * A question is a bubble; an answer is not. An answer can be several
 * paragraphs and a bubble that long is harder to read than plain text, so
 * Lex speaks in the page's own voice and only the learner's words are boxed.
 *
 * The controls under an answer appear once it has finished. Offering
 * regenerate or a rating while the words are still arriving invites judging
 * half a sentence, and a thumbs down on an answer nobody has read is worse
 * than no rating at all.
 */
export function Bubble({
  message,
  lang,
  onRegenerate,
  onRate,
  onUnrate,
}: {
  message: ChatMessage;
  /** The language Lex answers in: the notebook's meaning language. */
  lang: LanguageCode;
  onRegenerate: () => void;
  onRate: (verdict: 'up' | 'down', reason?: ApiLexReason) => void;
  onUnrate: () => void;
}): React.JSX.Element {
  const [asking, setAsking] = useState(false);
  const [copied, setCopied] = useState(false);
  const canSpeak = useCanSpeak(lang);

  // The copy button says so on itself for a moment rather than raising a
  // toast: it is a small, certain action, and a banner for it would cover
  // the answer it just copied.
  useEffect(() => {
    if (!copied) return undefined;
    const timer = setTimeout(() => {
      setCopied(false);
    }, COPIED_FOR_MS);
    return () => {
      clearTimeout(timer);
    };
  }, [copied]);

  if (message.role === 'user') {
    return (
      <div className={styles.fromMe}>
        <p className={styles.mine} dir={dirOf(message.text)}>
          {message.text}
        </p>
      </div>
    );
  }

  const done = message.status !== 'streaming' && message.live !== true;
  const failed = message.status === 'failed';
  const verdict = message.feedback?.verdict;

  return (
    <div className={styles.fromLex}>
      {/* Lex answers in the notebook's meaning language, so the answer can
          carry that writing system's face and leading like any other text
          in it. */}
      <div className={cx(styles.answer, scriptClass(lang))} lang={lang}>
        <Rich text={message.text} />
        {/* A caret while the words arrive, so a pause between tokens reads
            as thinking rather than as a screen that has stopped. */}
        {message.live === true && <span className={styles.caret} aria-hidden="true" />}
      </div>

      {failed && (
        <p className={styles.broke} role="status">
          {message.error !== undefined && message.error !== '' ? message.error : t('assistant.answerFailed')}
        </p>
      )}

      {done && (
        <div className={styles.tools}>
          {canSpeak && message.text !== '' && (
            <button
              type="button"
              className={styles.tool}
              aria-label={t('action.speak')}
              onClick={() => {
                platform.tts.speak(message.text, ttsLocaleOf(lang));
              }}
            >
              <Icon name="speaker" size={17} weight={1.9} />
            </button>
          )}
          {message.text !== '' && (
            <button
              type="button"
              className={cx(styles.tool, copied && styles.toolOn)}
              aria-label={copied ? t('assistant.copied') : t('assistant.copy')}
              onClick={() => {
                platform.share
                  .text(message.text)
                  .then(() => {
                    setCopied(true);
                  })
                  .catch(() => undefined);
              }}
            >
              <Icon name={copied ? 'check' : 'copy'} size={17} weight={1.9} />
            </button>
          )}
          <button
            type="button"
            className={styles.tool}
            aria-label={t('assistant.again')}
            onClick={onRegenerate}
          >
            <Icon name="undo" size={17} weight={1.9} />
          </button>
          {/* A gap, not a spacer: doing something with an answer and
              judging it are different jobs, and they sit apart rather than
              at opposite ends of the row. */}
          <span className={styles.toolGap} />
          <button
            type="button"
            className={cx(styles.tool, verdict === 'up' && styles.toolOn)}
            aria-label={t('assistant.good')}
            aria-pressed={verdict === 'up'}
            onClick={() => {
              if (verdict === 'up') onUnrate();
              else onRate('up');
            }}
          >
            <Icon name="thumbUp" size={17} weight={1.7} />
          </button>
          <button
            type="button"
            className={cx(styles.tool, verdict === 'down' && styles.toolOn)}
            aria-label={t('assistant.bad')}
            aria-pressed={verdict === 'down'}
            onClick={() => {
              if (verdict === 'down') {
                onUnrate();
                return;
              }
              // Recorded on the tap, then the reason is asked for. Somebody
              // who closes the sheet has still said it was poor, which is
              // the part worth keeping.
              onRate('down');
              setAsking(true);
            }}
          >
            <Icon name="thumbDown" size={17} weight={1.7} />
          </button>
        </div>
      )}

      {asking && (
        <Sheet
          title={t('assistant.whyTitle')}
          onClose={() => {
            setAsking(false);
          }}
        >
          <p className={styles.whyLead}>{t('assistant.whyLead')}</p>
          <ul className={styles.reasons}>
            {REASONS.map((reason) => (
              <li key={reason}>
                <button
                  type="button"
                  className={styles.reason}
                  onClick={() => {
                    onRate('down', reason);
                    setAsking(false);
                  }}
                >
                  {t(REASON_LABEL[reason])}
                </button>
              </li>
            ))}
          </ul>
        </Sheet>
      )}
    </div>
  );
}
